import numpy as np
import time


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _C_and_grad(h):
    """Return C and a subgradient direction (numpy array) w.r.t. h (unnormalized)."""
    h = np.asarray(h, dtype=float)
    n = len(h)
    s = h.sum()
    if s <= 0:
        return np.inf, np.zeros(n)
    conv = np.convolve(h, h)
    kmax = int(np.argmax(conv))
    M = conv[kmax]
    # dM/dh[i]: conv[k] = sum_j h[j] h[k-j], derivative at k=kmax
    gradM = np.zeros(n)
    for j in range(n):
        k = kmax - j
        if 0 <= k < n:
            gradM[j] += h[k]
    # C = 2 n M / s^2 ; dC = 2n (dM * s^2 - M*2 s * ds)/s^4
    # ds/dh[i] = 1
    C = 2.0 * n * M / (s * s)
    grad = 2.0 * n * (gradM * s * s - M * 2.0 * s) / (s ** 4)
    return C, grad


def _project_nonneg(x):
    return np.maximum(x, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

