    for Ntry in (200, 400, 800, 1500, 3000):
        if time.process_time() > deadline:
            break
        xx = (np.arange(Ntry) + 0.5) / Ntry - 0.5
        uu = 2.0 * xx
        for p in (0.5, 1.0, 1.5, 2.0, 3.0):
            hh = np.maximum(1.0 - uu * uu, 0.0) ** p + 1e-6
            candidates.append(hh)

    best = None
    bestC = np.inf
    for c in candidates:
        if time.process_time() > deadline:
            break
        cc = _C(c)
        if cc < bestC:
            bestC = cc
            best = c.copy()

