    def resample(h, N):
        if h.size == N:
            return h.copy()
        xo = np.linspace(0, 1, h.size)
        xn = np.linspace(0, 1, N)
        return np.maximum(np.interp(xn, xo, h), 0.0)

    # Try a couple of resolutions and pick best.
    for N in [800, 1600, 3200]:
        if time.process_time() > deadline:
            break
