from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(s, N):
    s = np.maximum(np.asarray(s, float).ravel(), 0.0)
    if s.size == N:
        return s.copy()
    xs = np.linspace(0, 1, s.size)
    xn = np.linspace(0, 1, N)
    return np.maximum(np.interp(xn, xs, s), 0.0)


def _grad_at(h, k):
    N = len(h)
    lo = max(0, k - N + 1)
    hi = min(N - 1, k)
    g = np.zeros(N)
    g[lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    return g


def _active_kset(conv, frac):
    M = conv.max()
    thresh = M * (1.0 - frac)
    ks = np.where(conv >= thresh)[0]
    if ks.size == 0:
        ks = np.array([int(np.argmax(conv))])
    return ks


def _refine(h, deadline, frac, maxiter, nknots):
    """L-BFGS on active set with up to nknots near-max knots treated as active."""
    N = len(h)
    conv = np.convolve(h, h)
    ks = _active_kset(conv, frac)
    if nknots and ks.size > nknots:
        order = np.argsort(-conv[ks])[:nknots]
        ks = ks[order]
    active = set()
    for k in ks:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        active.update(range(lo, hi + 1))
    active = np.array(sorted(active))
    if active.size < 4 or active.size > 12000:
        return h

    def f_and_g(x):
        hh = h.copy()
        hh[active] = np.maximum(x, 0.0)
        s = hh.sum()
        if s <= 0:
            return 1e10, np.zeros_like(x)
        cc = np.convolve(hh, hh)
        M = cc.max()
        C = 2.0 * N * M / (s * s)
        # average gradient over knots that are near-max
        kk_all = np.where(cc >= M * (1.0 - 1e-9))[0]
        if kk_all.size == 0:
            kk_all = np.array([int(np.argmax(cc))])
        g = np.zeros(N)
        for kk in kk_all:
            g += _grad_at(hh, int(kk))
        g /= kk_all.size
        dC = 2.0 * N * (g * s * s - M * 2.0 * s * hh) / (s ** 4)
        return C, dC[active]

    try:
        res = minimize(f_and_g, h[active].copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * len(active),
                       options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13})
        hh = h.copy()
        hh[active] = np.maximum(res.x, 0.0)
        if hh.sum() > 0:
            hh /= hh.sum()
            if _C(hh) < _C(h):
                return hh
    except Exception:
        pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size >= 1 and np.all(np.isfinite(s)) and np.any(s > 0):
            s = np.maximum(s, 0)
            candidates.append(s.copy())
            # increase resolution: finer N often lowers C
            for N in (500, 600, 800, 1000, 1200, 1600, 2000, 2400, 3000):
                if N != s.size:
                    candidates.append(_resample(s, N))

    if not candidates:
        N0 = 800
        x = np.linspace(-1.0, 1.0, N0)
        candidates.append(np.cos(np.pi * x / 2.0) ** 2 + 0.05)

    best = None
    bestC = np.inf
    for c in candidates:
        if c is None or c.sum() <= 0:
            continue
        c = c / c.sum()
        cc = _C(c)
        if cc < bestC:
            bestC = cc
            best = c.copy()

    h = best.copy()
    curC = bestC

    # alternate multi-knot and single-knot refinements, progressively finer
    fracs = [0.02, 0.01, 0.005, 0.002, 0.001, 0.0005, 0.0002, 0.0001, 5e-5]
    for frac in fracs:
        if time.process_time() >= deadline:
            break
        prev = curC
        h = _refine(h, deadline, frac, maxiter=80, nknots=20)
        h = _refine(h, deadline, frac, maxiter=120, nknots=1)
        curC = _C(h)
        if curC < bestC:
            bestC = curC
            best = h.copy()
        if curC >= prev - 1e-15 and frac < 0.001:
            break

    # final tight polish
    while time.process_time() < deadline:
        prev = bestC
        h = best.copy()
        h = _refine(h, deadline, frac=1e-5, maxiter=200, nknots=1)
        curC = _C(h)
        if curC < bestC:
            bestC = curC
            best = h.copy()
        else:
            break

    return np.maximum(best, 0.0)

