        h2 = _resample(best, N2)
        if h2.sum() <= 0:
            break
        h2 /= h2.sum()
        c2 = _C(h2)
        for frac in [0.005, 0.001, 2e-4, 5e-5, 1e-5]:
            if time.process_time() >= deadline:
                break
            h2 = _refine(h2, frac, maxiter=120, nknots=1)
            c2 = _C(h2)
        if c2 < bestC:
            bestC = c2
            best = h2.copy()
        else:
            if c2 > bestC + 1e-6:
                break

    # final tight polish and small perturbations
    rng = np.random.default_rng(987654321)
    scale = 0.005
    while time.process_time() < deadline:
        prev = bestC
        h = best.copy()
        h = _refine(h, 1e-6, maxiter=300, nknots=1)
        curC = _C(h)
        if curC < bestC:
            bestC = curC
            best = h.copy()
        else:
            break

    while time.process_time() < deadline:
        N = best.size
        trial = best * np.exp(scale * rng.standard_normal(N))
        trial = np.maximum(trial, 0.0)
        if trial.sum() <= 0:
            break
        trial /= trial.sum()
        trial = _refine(trial, 2e-4, maxiter=150, nknots=1)
        trial = _refine(trial, 1e-6, maxiter=200, nknots=1)
        curC = _C(trial)
        if curC < bestC - 1e-14:
            bestC = curC
            best = trial.copy()
            scale = max(scale * 0.8, 1e-4)
        else:
            scale = min(scale * 1.5, 0.05)

    return np.maximum(best, 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _resample(s, N):
    s = np.maximum(np.asarray(s, float).ravel(), 0.0)
    if s.size == N:
        return s.copy()
    xs = np.linspace(0, 1, s.size)
    xn = np.linspace(0, 1, N)
    return np.maximum(np.interp(xn, xs, s), 0.0)


def _grad_at(h, k):
    N = len(h)
    lo = max(0, k - N + 1)
    hi = min(N - 1, k)
    g = np.zeros(N)
    g[lo:hi + 1] = 2.0 * h[k - np.arange(lo, hi + 1)]
    return g


def _refine(h, frac, maxiter, nknots, deadline):
    N = len(h)
    conv = np.convolve(h, h)
    M = conv.max()
    ks = np.where(conv >= M * (1.0 - frac))[0]
    if ks.size == 0:
        ks = np.array([int(np.argmax(conv))])
    if nknots and ks.size > nknots:
        order = np.argsort(-conv[ks])[:nknots]
        ks = ks[order]
    active = set()
    for k in ks:
        lo = max(0, k - N + 1)
        hi = min(N - 1, k)
        active.update(range(lo, hi + 1))
    active = np.array(sorted(active))
    if active.size < 4 or active.size > 20000:
        return h

    def f_and_g(x):
        hh = h.copy()
        hh[active] = np.maximum(x, 0.0)
        s = hh.sum()
        if s <= 0:
            return 1e10, np.zeros_like(x)
        cc = np.convolve(hh, hh)
        Mv = cc.max()
        C = 2.0 * N * Mv / (s * s)
        kk_all = np.where(cc >= Mv * (1.0 - 1e-9))[0]
        if kk_all.size == 0:
            kk_all = np.array([int(np.argmax(cc))])
        g = np.zeros(N)
        for kk in kk_all:
            g += _grad_at(hh, int(kk))
        g /= kk_all.size
        dC = 2.0 * N * (g * s * s - Mv * 2.0 * s * hh) / (s ** 4)
        return C, dC[active]

    try:
        res = minimize(f_and_g, h[active].copy(), jac=True, method='L-BFGS-B',
                       bounds=[(0, None)] * len(active),
                       options={'maxiter': maxiter, 'ftol': 1e-16, 'gtol': 1e-13})
        hh = h.copy()
        hh[active] = np.maximum(res.x, 0.0)
        if hh.sum() > 0:
            hh /= hh.sum()
            if _C(hh) < _C(h):
                return hh
    except Exception:
        pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.85

    candidates = []
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size >= 1 and np.all(np.isfinite(s)) and np.any(s > 0):
            s = np.maximum(s, 0)
            candidates.append(s.copy())
            for N in (int(s.size * 1.5), int(s.size * 2), 800, 1200, 2000, 3000,
                      4500, 6000, 9000, 14000, 20000, 30000):
                if N != s.size and 1 <= N <= 30000:
                    candidates.append(_resample(s, N))

    if not candidates:
        N0 = 800
        x = np.linspace(-1.0, 1.0, N0)
        candidates.append(np.cos(np.pi * x / 2.0) ** 2 + 0.05)

    best = None
    bestC = np.inf
    for c in candidates:
        if c is None or c.sum() <= 0:
            continue
        c = c / c.sum()
        cc = _C(c)
        if cc < bestC:
            bestC = cc
            best = c.copy()

    h = best.copy()
    curC = bestC

    # progressive refinement at starting resolution
    for frac in [0.02, 0.01, 0.005, 0.002, 0.001, 0.0005, 0.0002, 1e-4, 5e-5, 1e-5]:
        if time.process_time() >= deadline:
            break
        prev = curC
        h = _refine(h, frac, maxiter=100, nknots=20, deadline=deadline)
        h = _refine(h, frac, maxiter=150, nknots=1, deadline=deadline)
        curC = _C(h)
        if curC < bestC:
            bestC = curC
            best = h.copy()
        if curC >= prev - 1e-15 and frac < 1e-3:
            break

    # upsample progressively
    while time.process_time() < deadline and best.size < 30000:
        N2 = min(30000, best.size * 2)
        h2 = _resample(best, N2)
        if h2.sum() <= 0:
            break
        h2 /= h2.sum()
        c2 = _C(h2)
        for frac in [0.005, 0.001, 2e-4, 5e-5, 1e-5]:
            if time.process_time() >= deadline:
                break
            h2 = _refine(h2, frac, maxiter=100, nknots=1, deadline=deadline)
            c2 = _C(h2)
        if c2 < bestC:
            bestC = c2
            best = h2.copy()
        else:
            if c2 > bestC + 1e-6:
                break

    # final tight polish
    h = best.copy()
    curC = bestC
    while time.process_time() < deadline:
        prev = curC
        h = _refine(h, 1e-6, maxiter=300, nknots=1, deadline=deadline)
        curC = _C(h)
        if curC < bestC:
            bestC = curC
            best = h.copy()
        if curC >= prev - 1e-15:
            break

    return np.maximum(best, 0.0)
